# 4 Tem 2026 — BÖLME ADIM 3: kanıt tabloları evidence.py'ye taşındı (birebir).
# SCANNER_TIER_MAP · ER_ELIT_SCORE_MIN · SCANNER_PLAIN_DESC · _guc_plain
# Eski elle girilmiş ER/Güç puanları kaldırıldı; sıralama güncel backtest özetinden gelir.
# ===============================================================
from evidence import (ER_ELIT_SCORE_MIN, SCANNER_PLAIN_DESC, _guc_plain,
                      is_ai_suppressed, alfa_deger)

# -> scanners.py (Adim 6b, 7 Tem 2026): _er_kisa_aciklama



@st.cache_data(ttl=600, show_spinner=False)
def get_scanner_scores():
    """Güncel backtest özetinden tarama puanı üretir.

    Taramanın kendi ölçülmüş ideal günü ve endeks üstü avantajı kullanılır. Bu alan
    eski bir özette hiç yoksa yalnız geriye uyumluluk için 5/10/20 pencerelerine
    bakılır. Düşüş uyarıları boğa puanlamasına hiç alınmaz. Örnek yetersizse,
    endeks üstü avantaj yoksa veya beklenti pozitif değilse puan yoktur.
    """
    MIN_N = 30
    try:
        import json as _ssj
        from pathlib import Path as _ssP
        _p = _ssP(__file__).parent / "backtest_results.json"
        if not _p.exists():
            return {}
        _summ = _ssj.loads(_p.read_text(encoding='utf-8')).get('summary', [])
    except Exception:
        return {}
    out = {}
    for r in _summ:
        _st = r.get('scan_type')
        _bias = str(r.get('bias', '') or '').lower()
        if not _st or 'bear' in _bias or _st in ('er_D4', 'er_D5'):
            continue
        _best = None  # (window, expectancy, per_day, n, source)
        _ideal_day = r.get('ideal_day')
        _ideal_ret = r.get('ideal_ret')
        _ideal_n = r.get('ideal_n') or 0
        _ideal_available = _ideal_day is not None and _ideal_ret is not None
        if _ideal_available:
            if _ideal_day and _ideal_n >= MIN_N and r.get('has_edge') is True:
                _best = (int(_ideal_day), float(_ideal_ret),
                         float(_ideal_ret) / int(_ideal_day), int(_ideal_n), 'ideal')
            else:
                continue
        else:
            for _w in (5, 10, 20):
                _exp = r.get(f'expectancy_{_w}g'); _n = r.get(f'eval_{_w}g') or 0
                if _exp is None or _n < MIN_N:
                    continue
                _pd = _exp / _w
                if _best is None or _pd > _best[2]:
                    _best = (_w, _exp, _pd, _n, 'fixed_fallback')
        if _best is None:
            continue
        _w, _exp, _pd, _n, _source = _best
        if _exp <= 0:
            continue
        out[_st] = {'score': int(max(0, min(100, round(40 + _pd * 150)))),
                    'window': _w, 'exp': round(_exp, 2), 'n': _n,
                    'source': _source}
    return out


def _compute_goldmine_entries():
    """Güncel backtest puanı olan pozitif taramaları hisse bazında sıralar."""
    try:
        entries = {}  # sym_clean -> dict(en yüksek puanlı sinyal) + extra sayacı

        def _push(sembol, icon, scanner, score, plain, guc=None, unmeasured=False,
                  scan_type=None):
            _sc = str(sembol).replace('.IS', '')
            if not _sc:
                return
            _family = scanner_family(scan_type or scanner)
            _cur = entries.get(_sc)
            if _cur is None:
                entries[_sc] = {'sym': _sc, 'sembol': sembol, 'icon': icon, 'scanner': scanner,
                                'score': score, 'plain': plain, 'guc': guc,
                                'unmeasured': unmeasured, 'extra': 0,
                                'families': {_family}, 'family_count': 1}
            else:
                _is_new_family = _family not in _cur['families']
                if _is_new_family:
                    _cur['families'].add(_family)
                    _cur['family_count'] = len(_cur['families'])
                    _cur['extra'] = _cur['family_count'] - 1
                # daha yüksek puanlı sinyal gelirse baş sinyali güncelle
                _cmp_new = -1 if unmeasured else score
                _cmp_old = -1 if _cur['unmeasured'] else _cur['score']
                if _cmp_new > _cmp_old:
                    _cur.update({'icon': icon, 'scanner': scanner, 'score': score,
                                 'plain': plain, 'guc': guc, 'unmeasured': unmeasured})

        # Veri-temelli puanlar. Özet yoksa/örnek azsa eski elle girilmiş puana düşülmez.
        _SS = get_scanner_scores()
        def _sscore(scan_type):
            v = _SS.get(scan_type)
            return int(v['score']) if v else None

        # 1) Erken Radar (senaryo bazlı güncel puan ≥ eşik)
        _er = st.session_state.get('erken_radar_data')
        if _er is not None and hasattr(_er, 'empty') and not _er.empty and {'Sembol', 'ScenarioId', 'Role'} <= set(_er.columns):
            _erp = _er[_er['Role'].isin(['primary', 'confirmation'])].copy()
            _erp['_sc'] = _erp['ScenarioId'].apply(lambda s: _sscore(f"er_{s}"))
            _erp = _erp[_erp['_sc'].notna()]
            _erp = _erp[_erp['_sc'] >= ER_ELIT_SCORE_MIN].sort_values('_sc', ascending=False)
            for _, r in _erp.iterrows():
                _push(r['Sembol'], '🎯', f"Erken Radar {r['ScenarioId']}", int(r['_sc']),
                      _er_kisa_aciklama(r['ScenarioId']), r.get('Guc'),
                      scan_type=f"er_{r['ScenarioId']}")

        # Harmonik Confluence gözlem katmanındadır; Gold Mine puanı ve sırası almaz.

        # 2) Pre-Launch BOS — 52H GÜÇ KALDIRILDI (20 Haz 2026). Denetim: 🟢(52H≥60) 5g −%2.31 /
        # 10g −%4.06 PARA KAYBETTİRİYOR (VIP'ten beter), 🟡-orta +%1.09. Mantık: zirveye yakınsa
        # fırlama ÇOKTAN olmuş = geç → 52H yine yanlış eksen. 🔴 dışlaması + 🟢 boost iyi sinyalleri
        # atıp kaybedenleri tutuyordu. Düz nötr puan, guc=None. Candidate (🟡-orta) izlemede, n ince.
        _pb = st.session_state.get('prelaunch_bos_data')
        if _pb is not None and hasattr(_pb, 'empty') and not _pb.empty and 'Sembol' in _pb.columns:
            _pb_score = _sscore('prelaunch_bos')
            if _pb_score is not None:
                for _, r in _pb.iterrows():
                    _push(r['Sembol'], '🚀', 'Pre-Launch BOS', _pb_score,
                          SCANNER_PLAIN_DESC['prelaunch'], scan_type='prelaunch_bos')

        # 3) Altın / Platin / VIP puan değildir; uygunluk rozeti olarak üyelik panelinde kalır.

        # 4) Gizli Birikim — yalnız güncel pozitif karne varsa gösterilir.
        _ac = st.session_state.get('accum_data')
        if _ac is not None and hasattr(_ac, 'empty') and not _ac.empty and 'Sembol' in _ac.columns:
            _ac_score = _sscore('gizli_birikim')
            if _ac_score is not None:
                for _, r in _ac.iterrows():
                    _push(r['Sembol'], '🔍', 'Gizli Birikim', _ac_score,
                          SCANNER_PLAIN_DESC['gizli'], scan_type='gizli_birikim')

        # NOT (19 Haz 2026 — düzeltme): Altın/Platin/Minervini vitrine ALINMIYOR. Backtest puanları
        # yok ("kanıt bekliyor") + generic açıklamaları yanıltıcıydı (AKBNK 60g %91/RSI83 iken
        # "henüz pahalılaşmamış" diyordu). Vitrin = yalnız güncel pozitif karneli. Onlar alttaki dedike
        # "Altın Set-up & VIP" panelinde + mini panelde gerçek verisiyle duruyor.

        if not entries:
            return []
        # Sırala: (1) backtest puanı yüksek, (2) aynı puanda GÜÇLÜ konum öne (🟢<🟡<🔴), (3) alfabe
        def _grank(g):
            g = str(g or '')
            return 0 if '🟢' in g else (2 if '🔴' in g else 1)
        _ranked = sorted(entries.values(), key=lambda e: (-e.get('score', 0), _grank(e.get('guc')), e['sym']))
        return _ranked
    except Exception:
        return []


def _cap_goldmine_entries(ranked):
    """Vitrin/log çeşitliliğini korur; karar motorunun ham aday listesine uygulanmaz."""
    _capped = []; _seen = {}
    for e in (ranked or []):
        k = e.get('scanner', '')
        _seen[k] = _seen.get(k, 0) + 1
        if _seen[k] <= 5:
            _capped.append(e)
    return _capped


def log_goldmine_selection(category="", top_n=20):
    """Vitrinin o günkü top seçimlerini goldmine_log'a yazar (META-BACKTEST için, 19 Haz 2026).
    Master Scan sonunda çağrılır. Idempotent (INSERT OR IGNORE: aynı gün+sembol bir kez).
    Sonra signal_results JOIN ile vitrin sıralamasının gerçek getirisi ölçülür."""
    conn = None
    _write_guard = None
    try:
        ranked = _cap_goldmine_entries(_compute_goldmine_entries())
        if not ranked:
            return True
        today = datetime.now(_TZ_ISTANBUL).strftime("%Y-%m-%d")
        _write_guard = patron_db_guard.database_write_lock("goldmine_log")
        _write_guard.__enter__()
        conn = sqlite3.connect(DB_FILE, timeout=60)
        c = conn.cursor()
        write_errors = 0
        for i, e in enumerate(ranked[:top_n]):
            try:
                c.execute(
                    "INSERT OR IGNORE INTO goldmine_log "
                    "(scan_date, symbol, rank, score, scanner, confluence_count, unmeasured, category) "
                    "VALUES (?,?,?,?,?,?,?,?)",
                    (today, str(e.get('sembol', e['sym'])), i + 1,
                     None if e.get('unmeasured') else float(e.get('score', 0)),
                     str(e.get('scanner', '')), int(e.get('family_count', 1)),
                     1 if e.get('unmeasured') else 0, category)
                )
            except Exception as write_error:
                write_errors += 1
                logging.warning(f"[log_goldmine_selection] HATA — sıra={i + 1}: {write_error}")
        if write_errors:
            raise RuntimeError(f"Gold Mine yazımında {write_errors} satır kaybedildi")
        conn.commit()
        saved_count = c.execute(
            "SELECT COUNT(*) FROM goldmine_log WHERE scan_date=?", (today,)
        ).fetchone()[0]
        if saved_count <= 0:
            raise RuntimeError("Gold Mine adayları vardı ancak günlüğe hiç satır yazılmadı")
        return True
    except Exception as _e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        try:
            log_error("log_goldmine_selection", _e, category)
        except Exception:
            pass
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        if _write_guard is not None:
            try:
                _write_guard.__exit__(None, None, None)
            except Exception:
                pass


def render_gold_mine_showcase():
    """🏆 GOLD MINE VİTRİNİ — İKİ SÜTUN: konum ayraç, güncel puan sütun-içi sıra.
    Sol = pozitif karne + güçlü/orta konum · Sağ = pozitif karne + zayıf konum.
    Dönüş: True (içerik gösterildi) / False (boş)."""
    try:
        _ranked = _cap_goldmine_entries(_compute_goldmine_entries())
        if not _ranked:
            return False

        def _is_weak(e):
            return '🔴' in str(e.get('guc') or '')
        _left = [e for e in _ranked if not _is_weak(e)][:10]   # hazır (güçlü/orta/güç-yok)
        _right = [e for e in _ranked if _is_weak(e)][:10]       # izle (zayıf konum)

        st.markdown(
            "<div style='background:linear-gradient(90deg,#422006,#1c1917);border:1px solid #a16207;"
            "border-radius:8px;padding:6px 11px;margin:6px 0 5px 0;font-size:0.82rem;font-weight:900;"
            "color:#fbbf24;letter-spacing:0.03em;'>🏆 GOLD MINE — Güncel Pozitif Karneli Sinyaller</div>",
            unsafe_allow_html=True
        )

        def _gm_col(items, side, title, sub, accent, empty_msg):
            st.markdown(
                f"<div style='background:{accent}14;border:1px solid {accent}55;border-radius:7px;"
                f"padding:5px 9px;margin-bottom:5px;'>"
                f"<div style='font-size:0.76rem;font-weight:900;color:{accent};'>{title}</div>"
                f"<div style='font-size:0.64rem;color:#94a3b8;line-height:1.2;'>{sub}</div></div>",
                unsafe_allow_html=True
            )
            if not items:
                st.markdown(f"<div style='border:1px dashed {accent}44;border-radius:6px;padding:12px 8px;"
                            f"text-align:center;color:#94a3b8;font-size:0.72rem;'>{empty_msg}</div>",
                            unsafe_allow_html=True)
                return
            with st.container(height=320, border=False):
                for _i, e in enumerate(items):
                    if st.button(f"{_i+1}. {e['icon']} {e['sym']} · {e['scanner']}",
                                 key=f"gm_{side}_{e['sym']}_{_i}", width='stretch'):
                        on_scan_result_click(e['sembol']); st.rerun()
                    _d = e['plain']
                    if len(_d) > 70:
                        _d = _d[:67].rstrip() + '…'
                    _extra = f" · +{e['extra']} bağımsız aile" if e['extra'] else ""
                    st.markdown(
                        f"<div style='font-size:0.69rem;color:#cbd5e1;margin:-6px 0 4px 6px;line-height:1.3;'>"
                        f"<span style='color:#fbbf24;font-weight:800;'>puan {e['score']}</span>{_extra} — {_d}</div>",
                        unsafe_allow_html=True
                    )

        _cL, _cR = st.columns(2)
        with _cL:
            _gm_col(_left, "L", "💪 POZİTİF KARNE + UYGUN KONUM",
                    "Kendi ölçülmüş vadesinde pozitif + şu an konumu güçlü", "#22c55e",
                    "Şu an pozitif karneli ve güçlü konumda sinyal yok.")
        with _cR:
            _gm_col(_right, "R", "⏳ POZİTİF KARNE, ZAYIF KONUM",
                    "Karnesi pozitif ama şu an dipte/zayıf — izle", "#f59e0b",
                    "Şu an zayıf konumda pozitif karneli sinyal yok.")
        return True
    except Exception:
        return False


# ══ BUGÜN — BİRLEŞİK AL-İZLE LİSTESİ (render redesign, 11 Ağu 2026) ══════════
# GOLD MINE karne omurgası (kanıt) + zamanlama (kirilima_yakin_form aşaması) + kesişim.
# KOVA bazlı sıra (ince puan değil — sahte hassasiyet yok): ELİT > güvenilir > ölçülmemiş,
# kova içinde zamanlama (kırılıyor>yakın) → kesişim → puan. Tek liste; taramalar = rozet.
def _bugun_stage_map():
    ky = st.session_state.get('kirilima_yakin_form')
    out = {}
    try:
        if ky is not None and hasattr(ky, 'empty') and not ky.empty:
            for _, r in ky.iterrows():
                _s = str(r.get('Sembol', '')).replace('.IS', '')
                out[_s] = {'durum': r.get('Durum'), 'mesafe': r.get('Mesafe'), 'yon': r.get('Yon')}
    except Exception:
        pass
    return out


def _compute_bugun_entries():
    try:
        base = _compute_goldmine_entries()
        stg = _bugun_stage_map()
        rows = []
        for e in base:
            _sym = e['sym']
            _bucket = 2 if e.get('unmeasured') else (0 if e.get('score', 0) >= 85 else 1)
            _d = stg.get(_sym, {}).get('durum')
            _srank = {'KIRILDI': 0, 'YAKIN': 1}.get(_d, 2)
            rows.append({**e, 'bucket': _bucket, 'stage': stg.get(_sym, {}), 'stage_rank': _srank})
        rows.sort(key=lambda e: (e['bucket'], e['stage_rank'],
                                 -e.get('family_count', 1), -e.get('score', 0), e['sym']))
        return rows
    except Exception:
        return []


def _render_stp_uyanis_master_panel():
    """Master Scan'in STP gözlem havuzu — skora ve AI kararına bağımsızdır."""
    _df = st.session_state.get('stp_uyanis_data')
    if _df is None:
        _df = pd.DataFrame()

    _count = len(_df) if hasattr(_df, 'empty') and not _df.empty else 0
    st.markdown(
        "<div style='margin:0 0 6px;padding:7px 9px;border:1px solid rgba(245,158,11,0.42);"
        "border-radius:8px;background:rgba(245,158,11,0.08);'>"
        "<div style='font-size:0.78rem;color:#fbbf24;font-weight:900;'>⚗ STP TEYİTLİ TEPKİ · GÖZLEM</div>"
        "<div style='font-size:0.64rem;color:#cbd5e1;margin-top:2px;'>"
        "15+ gün baskı (1 kısa tepki tolere) → T+2 teyit / T+5 planı · "
        "7–14 gün kesintisiz → yalnız erken izleme · skor/AI dışı</div></div>",
        unsafe_allow_html=True,
    )
    if _count == 0:
        st.caption("Bu Master Scan'de aktif STP tepki adayı yok.")
        return

    # Uzun baskı grubu plan takibine, 7–14 günlük grup ise yalnız erken izlemeye
    # gider. Aynı sınıf içinde zamanlama ve kesişim kalitesi sıralanır.
    try:
        _panel_df = _df.copy()
        _panel_df['_stp_age_rank'] = (
            pd.to_numeric(_panel_df['Olay_Gunu'], errors='coerce')
            .map({3: 0, 4: 1, 5: 2}).fillna(3)
        )
        _panel_df['_stp_valid_rank'] = (
            _panel_df['Durum_Kodu'].map({'recross_down': 1, 'invalid': 2}).fillna(0)
        )
        _panel_df['_stp_pressure_rank'] = pd.to_numeric(
            _panel_df.get('Baski_Sira', _panel_df['Baski_Gun']), errors='coerce').fillna(0)
        _panel_df['_stp_breakout_rank'] = _panel_df['Anlamli_Kesis'].fillna(False).astype(bool).astype(int)
        _panel_df = _panel_df.sort_values(
            by=['_stp_valid_rank', '_stp_pressure_rank', '_stp_age_rank', '_stp_breakout_rank', 'Olay_Gunu', 'Sembol'],
            ascending=[True, False, True, False, True, True],
        )
    except Exception:
        _panel_df = _df

    _state_colors = {
        'confirmed': '#34d399', 'active': '#34d399', 'exit': '#fbbf24',
        't1': '#fbbf24', 't0': '#fbbf24', 'recross_down': '#f87171',
        'invalid': '#f87171',
    }
    with st.container(height=430, border=False):
        for _idx, _row in _panel_df.head(16).iterrows():
            _sym = str(_row.get('Sembol', ''))
            _state = str(_row.get('Durum_Kodu', ''))
            _days = int(_row.get('Baski_Gun', 0) or 0)
            _early_raw = _row.get('Erken_Izleme')
            _early = (bool(_early_raw) if pd.notna(_early_raw) else 7 <= _days < 15)
            _color = '#fbbf24' if _early and _state not in ('recross_down', 'invalid') else _state_colors.get(_state, '#94a3b8')
            _price = _row.get('Fiyat', 0)
            try:
                _price_txt = f"{float(_price):.2f}"
            except Exception:
                _price_txt = str(_price)
            _pressure_txt = str(_row.get('Baski_Etiketi') or f"{_days}g baskı")
            _vol = _row.get('Hacim_Kat')
            _vol_txt = f" · Hacim ×{float(_vol):.1f}" if pd.notna(_vol) else ''
            _candle = str(_row.get('Mum', '—'))
            _display_state = 'ERKEN İZLEME' if _early and _state not in ('recross_down', 'invalid') else _row.get('Durum', '')
            _label = f"{_sym.replace('.IS', '')}  {_price_txt} · {_display_state}"
            if st.button(_label, key=f"stp_uyanis_card_{_sym}_{_idx}", width='stretch'):
                on_scan_result_click(_sym)
                st.rerun()
            st.markdown(
                f"<div style='margin:-5px 0 5px 5px;font-size:0.66rem;color:{_color};font-weight:700;'>"
                f"{_pressure_txt} · {_candle}{_vol_txt}</div>",
                unsafe_allow_html=True,
            )


