@st.cache_data(ttl=600, show_spinner=False)
def evaluate_signals(lookback_days=90, forward_windows=None):
    """
    scan_signals tablosundaki sinyalleri değerlendirir.
    Her sinyal için +5, +10, +20 günlük fiyat getirisini hesaplar.
    Minimum 5 gün geçmemiş sinyaller atlanır (henüz olgunlaşmamış).
    Parquet cache üzerinden çalışır — ek internet isteği yapmaz.
    Cache: 10 dakika (DB nadiren güncellenir, Streamlit her render'da çağırmasın).
    """
    if forward_windows is None:
        forward_windows = [5, 10, 20]

    try:
        conn = sqlite3.connect(DB_FILE, timeout=30)
        signals = pd.read_sql(
            "SELECT * FROM scan_signals WHERE scan_date >= date('now', ?) "
            "AND COALESCE(is_event_start, 1)=1",
            conn,
            params=(f'-{lookback_days} days',)
        )
        conn.close()
    except Exception:
        return pd.DataFrame()

    if signals.empty:
        return pd.DataFrame()

    today = datetime.now(_TZ_ISTANBUL).date()
    results = []

    # 14 Tem 2026 — PERFORMANS KÖK FIX: eski kod her sinyal SATIRI için
    # get_safe_historical_data çağırıyordu → seans içinde her benzersiz hisse
    # Yahoo+İsyatirim AĞ ÇEKİMİ tetikliyordu (binlerce satır × saniyeler =
    # dakikalarca donan render; py-spy suçüstü yakaladı: İsyatirim SSL read).
    # Geçmiş getiri hesabına bugünün barı GEREKMEZ → parquet DİSKTEN,
    # sembol başına 1 KEZ okunur. Docstring'in "ek internet isteği yapmaz"
    # sözü artık gerçekten doğru.
    _hist_cache = {}
    def _load_hist(sym):
        if sym in _hist_cache:
            return _hist_cache[sym]
        df_h = None
        try:
            _adaylar = [f"{sym}_1d.parquet"]
            if not str(sym).endswith(".IS"):
                _adaylar.append(f"{sym}.IS_1d.parquet")
            for _cand in _adaylar:
                _pq = os.path.join("veriler", _cand)
                if os.path.exists(_pq):
                    df_h = pd.read_parquet(_pq).sort_index()
                    break
        except Exception:
            df_h = None
        _hist_cache[sym] = df_h
        return df_h

    for _, sig in signals.iterrows():
        try:
            signal_date = pd.to_datetime(sig['scan_date']).date()
            days_elapsed = (today - signal_date).days
            if days_elapsed < min(forward_windows):
                continue  # henüz değerlendirilemez

            # Diskteki parquet'ten tarihi veri al (ağ YOK, sembol başına 1 okuma)
            df_hist = _load_hist(sig['symbol'])
            if df_hist is None or df_hist.empty:
                continue

            # Sinyal tarihine en yakın index'i bul
            sig_ts = pd.Timestamp(sig['scan_date'])
            idx_arr = df_hist.index.searchsorted(sig_ts)
            if idx_arr >= len(df_hist):
                continue

            _entry_info = resolve_next_open_entry(
                df_hist, sig['scan_date'], bias=sig.get('bias', 'bullish'),
                apply_bist_limit=(
                    not str(sig.get('category', '') or '').strip()
                    or 'BIST' in str(sig.get('category', '') or '').upper()
                    or str(sig['symbol']).upper().endswith('.IS')
                ),
                max_locked_sessions=3,
            )
            if not str(_entry_info.get('status', '')).startswith('filled'):
                continue
            entry = float(_entry_info['entry_price'])
            entry_idx = int(_entry_info['entry_pos'])

            row_result = {
                'Sembol':        sig['symbol'],
                'Tarama':        sig['scan_type'],
                'Sinyal Tarihi': sig['scan_date'],
                'Giriş Tarihi':  _entry_info['entry_date'],
                'Giriş':         round(entry, 2),
                'Açılış Farkı %': _entry_info.get('entry_gap_pct'),
                'Giriş Gecikmesi': _entry_info.get('entry_delay', 0),
                'Geçen Gün':     days_elapsed,
                'Kategori':      sig.get('category', ''),
            }

            for fwd in forward_windows:
                fwd_idx = entry_idx + fwd - 1
                if fwd_idx < len(df_hist):
                    fwd_price = float(df_hist['Close'].iloc[fwd_idx])
                    ret = (fwd_price - entry) / entry * 100
                    row_result[f'Getiri_{fwd}G'] = round(ret, 2)
                    row_result[f'Hit_{fwd}G']    = ret > 0
                else:
                    row_result[f'Getiri_{fwd}G'] = None
                    row_result[f'Hit_{fwd}G']    = None

            results.append(row_result)
        except Exception:
            continue

    return pd.DataFrame(results) if results else pd.DataFrame()


def get_signal_performance_summary(lookback_days=90):
    """
    evaluate_signals() çıktısını scan_type bazında özetler.
    Hit rate, ortalama getiri ve sinyal sayısını döndürür.
    Minimum 3 değerlendirilebilir sinyal yoksa o satırı — gösterir.
    """
    df = evaluate_signals(lookback_days=lookback_days)
    if df.empty:
        return pd.DataFrame()

    scan_labels = {
        'guclu_donus':    '💪 Güçlü Dönüş',
        'nadir_firsat':   '🔥 Nadir Set-up',
        'minervini':      '📈 Minervini SEPA',
        'rs_leaders':     '🚀 RS Momentum',
        'golden_pattern': '⭐ Altın Formasyon',
    }
    # Erken Radar senaryo etiketleri (er_A1, er_B4, ...) — dinamik ekle
    try:
        _cat_icons = {'A': '🔄', 'B': '📐', 'C': '🚀', 'D': '⚠'}
        for _sid, _scn in ERKEN_RADAR_SCENARIOS.items():
            scan_labels[f"er_{_sid}"] = f"{_cat_icons.get(_scn['category'], '•')} ER {_sid} · {_scn['name']}"
    except NameError:
        pass  # ERKEN_RADAR_SCENARIOS henüz tanımlı değilse (import sırası)

    summary = []
    for scan_type, grp in df.groupby('Tarama'):
        row = {
            'Tarama':  scan_labels.get(scan_type, scan_type),
            'Sinyal':  len(grp),
        }
        for fwd in [5, 10, 20]:
            col_hit = f'Hit_{fwd}G'
            col_ret = f'Getiri_{fwd}G'
            valid_hits = grp[col_hit].dropna()
            valid_rets  = grp[col_ret].dropna()
            if len(valid_hits) >= 3:
                row[f'Hit {fwd}G']  = f"%{round(valid_hits.mean() * 100, 1)}"
                row[f'Ort +{fwd}G'] = f"%{round(valid_rets.mean(), 2):+.2f}"
            else:
                row[f'Hit {fwd}G']  = f"— (n={len(valid_hits)})"
                row[f'Ort +{fwd}G'] = "—"
        summary.append(row)

    return pd.DataFrame(summary)


