def render_detail_card_advanced(ticker):
    ACIKLAMALAR = {
        "Squeeze": "🚀 Squeeze: Bollinger Bant genişliği son 60 günün en dar aralığında (Patlama Hazır)",
        "Trend": "⚡ Trend: EMA5 > EMA20 üzerinde (Yükseliyor)",
        "MACD": "🟢 MACD: Histogram bir önceki günden yüksek (Momentum Artışı Var)",
        "Hacim": "🔊 Hacim: Son 5 günlük hacim ortalama hacmin %20 üzerinde",
        "Breakout": "🔨 Breakout: Fiyat son 20 gün zirvesinin %98 veya üzerinde",
        "RSI Güçlü": "⚓ RSI Güçlü: 30-65 arasında ve artışta",
        "Hacim Patlaması": "💥 Hacim son 20 gün ortalamanın %30 üzerinde seyrediyor",
        "RS (S&P500)": "💪 Hisse, Endeksten daha güçlü",
        "Boğa Trendi": "🐂 Boğa Trendi: Fiyat Üç Ortalamanın da (SMA50 > SMA100 > SMA200) üzerinde",
        "60G Zirve": "⛰️ Zirve: Fiyat son 60 günün tepesine %97 yakınlıkta",
        "RSI Bölgesi": "🎯 RSI Uygun: Pullback için uygun (40-55 arası)",
        "Ichimoku": "☁️ Ichimoku: Fiyat Bulutun Üzerinde (Trend Pozitif)",
        "RS": "💪 Relatif Güç (RS)",
        "Setup": "🛠️ Setup Durumu",
        "ADX Durumu": "💪 ADX Trend Gücü"
    }

    display_ticker = get_display_name(ticker)
    dt = get_tech_card_data(ticker)
    info = fetch_stock_info(ticker)
    
    price_val = f"{info['price']:.2f}" if info else "Veri Yok"
    ma_vals = f"SMA50: {dt['sma50']:.0f} | SMA200: {dt['sma200']:.0f}" if dt else ""
    stop_vals = f"{dt['stop_level']:.2f} (Risk: %{dt['risk_pct']:.1f})" if dt else ""

    # RADAR 1 VERİSİ
    r1_res = {}; r1_score = 0
    if st.session_state.scan_data is not None:
        row = st.session_state.scan_data[st.session_state.scan_data["Sembol"] == ticker]
        if not row.empty and "Detaylar" in row.columns: r1_res = row.iloc[0]["Detaylar"]; r1_score = row.iloc[0]["Skor"]
    if not r1_res:
        temp_df = analyze_market_intelligence([ticker], st.session_state.get('category', 'S&P 500'))
        if not temp_df.empty and "Detaylar" in temp_df.columns: r1_res = temp_df.iloc[0]["Detaylar"]; r1_score = temp_df.iloc[0]["Skor"]

    # RADAR 2 VERİSİ
    r2_res = {}; r2_score = 0
    if st.session_state.radar2_data is not None:
        if "Sembol" not in st.session_state.radar2_data.columns:
            st.session_state.radar2_data = st.session_state.radar2_data.reset_index()
            st.session_state.radar2_data.rename(columns={'index': 'Sembol', 'Symbol': 'Sembol', 'Ticker': 'Sembol'}, inplace=True)
        row = st.session_state.radar2_data[st.session_state.radar2_data["Sembol"] == ticker]
        if not row.empty and "Detaylar" in row.columns: r2_res = row.iloc[0]["Detaylar"]; r2_score = row.iloc[0]["Skor"]
    if not r2_res:
        temp_df2 = radar2_scan([ticker])
        if not temp_df2.empty and "Detaylar" in temp_df2.columns: r2_res = temp_df2.iloc[0]["Detaylar"]; r2_score = temp_df2.iloc[0]["Skor"]

    r1_suffix = ""
    if r1_score < 2: r1_suffix = " <span style='color:#f87171; font-weight:500; background:rgba(248,113,113,0.08); padding:1px 4px; border-radius:3px; margin-left:5px; font-size:0.7rem;'>(⛔ ÖN FİLTREDE ZAYIF)</span>"
    elif r1_score > 5: r1_suffix = " <span style='color:#16a34a; font-weight:500; background:rgba(16,185,129,0.07); padding:1px 4px; border-radius:3px; margin-left:5px; font-size:0.7rem;'>(✅ ÖN FİLTREYİ GEÇTİ)</span>"

    def get_icon(val): return "✅" if val else "❌"

    # RADAR 1 HTML (FİLTRELİ)
    r1_html = ""
    for k, v in r1_res.items():
        if k in ACIKLAMALAR: 
            text = ACIKLAMALAR.get(k, k); is_valid = v
            if isinstance(v, (tuple, list)): 
                is_valid = v[0]; val_num = v[1]
                if k == "RSI Güçlü":
                    if is_valid:
                        # 30-65 arası ve yükseliyorsa
                        text = f"⚓ RSI Güçlü/İvmeli: ({int(val_num)})"
                    else:
                        # Eğer çarpı yemişse sebebini yazalım
                        if val_num >= 65:
                            text = f"🔥 RSI Şişkin (Riskli Olabilir): ({int(val_num)})"
                        elif val_num <= 30:
                            text = f"❄️ RSI Zayıf (Dipte): ({int(val_num)})"
                        else:
                            text = f"📉 RSI İvme Kaybı: ({int(val_num)})"
                elif k == "ADX Durumu": text = f"💪 ADX Güçlü: {int(val_num)}" if is_valid else f"⚠️ ADX Zayıf: {int(val_num)}"
            r1_html += f"<div class='tech-item' style='margin-bottom:2px;'>{get_icon(is_valid)} <span style='margin-left:4px;'>{text}</span></div>"

    # RADAR 2 HTML (FİLTRELİ ve DÜZELTİLMİŞ)
    r2_html = ""
    for k, v in r2_res.items():
        if k in ACIKLAMALAR:
            text = ACIKLAMALAR.get(k, k); is_valid = v
            
            if isinstance(v, (tuple, list)): 
                is_valid = v[0]; val_num = v[1]
                if k == "RSI Bölgesi": 
                    if is_valid:
                        text = f"🎯 RSI Uygun: ({int(val_num)})"
                    else:
                        # Eğer geçerli değilse nedenini yazalım
                        if val_num > 65:
                            text = f"🔥 RSI Şişkin (Riskli Olabilir): ({int(val_num)})"
                        else:
                            text = f"❄️ RSI Zayıf: ({int(val_num)})"

            # Ichimoku Özel Kontrolü (Gerekirse)
            if k == "Ichimoku":
                # Eğer özel bir şey yapmak istersen buraya, yoksa standart metin gelir
                pass 

            r2_html += f"<div class='tech-item' style='margin-bottom:2px;'>{get_icon(is_valid)} <span style='margin-left:4px;'>{text}</span></div>"

    full_html = f"""
    <div class="info-card">
        <div class="info-header">📋 Gelişmiş Teknik Kart: {display_ticker}</div>
        <div style="display:flex; justify-content:space-between; margin-bottom:8px; border-bottom:1px solid #1e3a5f; padding-bottom:4px;">
            <div style="font-size:0.8rem; font-weight:700; color:#38bdf8;">Fiyat: {price_val}</div>
            <div style="font-size:0.75rem; color:#64748B;">{ma_vals}</div>
        </div>
        <div style="font-size:0.8rem; color:#f87171; margin-bottom:8px;">🛑 Stop: {stop_vals}</div>
        <div style="background:rgba(56,189,248,0.05); padding:4px; border-radius:4px; margin-bottom:4px;">
            <div style="font-weight:700; color:#38bdf8; font-size:0.75rem; margin-bottom:4px;">🧠 RADAR 1 ÖN FİLTRE (fırsat sinyali değil): Momentum ve Hacim - SKOR: {r1_score}/7{r1_suffix}</div>
            <div class="tech-grid" style="font-size:0.75rem;">{r1_html}</div>
        </div>
        <div style="background:rgba(16,185,129,0.07); padding:4px; border-radius:4px;">
            <div style="font-weight:700; color:#4ade80; font-size:0.75rem; margin-bottom:4px;">🚀 RADAR 2 (10-50 gün): Trend Takibi - SKOR: {r2_score}/7</div>
            <div class="tech-grid" style="font-size:0.75rem;">{r2_html}</div>
        </div>
    </div>
    """
    st.markdown(full_html.replace("\n", " "), unsafe_allow_html=True)

def render_synthetic_sentiment_panel(data):
    if data is None or data.empty: return
    display_ticker = get_display_name(st.session_state.ticker)
    
    info = fetch_stock_info(st.session_state.ticker)
    current_price = info.get('price', 0) if info else 0
    
    header_color = "#3b82f6" 
    _cp_header_str = (f"{int(current_price):,}".replace(",", ".") if current_price >= 1000 else f"{current_price:.2f}")
    st.markdown(f"""
    <div class="info-card" style="border-top: 3px solid {header_color}; margin-bottom:15px;">
        <div class="info-header" style="color:#38bdf8; display:flex; justify-content:space-between; align-items:center;">
            <span style="font-size:1.1rem;">🌊 Para Akış İvmesi & Fiyat Dengesi: {display_ticker}</span>
            <span style="font-family:'JetBrains Mono'; font-weight:700; color:#f1f5f9; background:rgba(56,189,248,0.05); padding:2px 8px; border-radius:4px; font-size:1.25rem;">
                {_cp_header_str}
            </span>
        </div>
    </div>
    """, unsafe_allow_html=True)
    _price_fmt = ',.0f' if data['Price'].max() >= 1000 else '.2f'
    # Hacim etiket kolonlarını ana data'ya ekle (bar tooltip için)
    if 'Volume' in data.columns and 'Vol_Avg20' in data.columns and 'RVOL' in data.columns:
        def _fv(v):
            try:
                v = float(v)
                if v >= 1e6: return f"{v/1e6:.2f}M"
                if v >= 1e3: return f"{v/1e3:.0f}K"
                return f"{v:.0f}"
            except: return "—"
        data = data.copy()
        data['VolStr']    = data['Volume'].apply(_fv)
        data['VolAvgStr'] = data['Vol_Avg20'].apply(_fv)
        data['RVOLStr']   = data['RVOL'].apply(lambda x: f"{x:.2f}x" if pd.notna(x) else "—")
    c1, c2 = st.columns([1, 1]); x_axis = alt.X('Date_Str', axis=alt.Axis(title=None, labelAngle=-45, labelOverlap=False, labelColor="#94a3b8"), sort=None)
    with c1:
        base = alt.Chart(data).encode(x=x_axis)
        color_condition = alt.condition(
            alt.datum.MF_Smooth > 0,
            alt.value("#5B84C4"),
            alt.value("#ef4444")
        )
        _tt1 = [
            alt.Tooltip('Date_Str:N',  title='Tarih'),
            alt.Tooltip('Price:Q',     title='Kapanış',   format=_price_fmt),
            alt.Tooltip('MF_Smooth:Q', title='Para Akışı', format='.2f'),
            alt.Tooltip('VolStr:N',    title='Hacim'),
            alt.Tooltip('VolAvgStr:N', title='20g Ort.'),
            alt.Tooltip('RVOLStr:N',   title='RVOL'),
        ] if all(c in data.columns for c in ['VolStr','VolAvgStr','RVOLStr']) else [
            alt.Tooltip('Date_Str:N',  title='Tarih'),
            alt.Tooltip('Price:Q',     title='Kapanış',   format=_price_fmt),
            alt.Tooltip('MF_Smooth:Q', title='Para Akışı', format='.2f'),
        ]
        # 10 Tem 2026 — SABİT EKSEN: barlar σ×10 ölçeğinde → ±30 = ±3σ. Sakin gün
        # küçük bar görünür (otomatik zoom 'her pencere coşkulu' etkisi kalkar);
        # ±30'u aşan nadir bar olursa eksen o bara göre genişler (kırpma yok).
        _mf_lim = max(30.0, float(data['MF_Smooth'].abs().max()) * 1.05)
        bars = base.mark_bar(size=12, opacity=0.9).encode(
            y=alt.Y('MF_Smooth:Q', scale=alt.Scale(domain=[-_mf_lim, _mf_lim]),
                    axis=alt.Axis(title='Para Akışı (Güç)', labels=False, titleColor='#64748b')),
            color=color_condition,
            tooltip=_tt1
        )
        price_line = base.mark_line(color='#bfdbfe', strokeWidth=2).encode(
            y=alt.Y('Price:Q', scale=alt.Scale(zero=False), axis=None)
        )
        # ─── ANNOTATION: Olağandışı hacim (RVOL ≥ 2.0x) — halka işaretler ───
        # FX/kripto/endeks: Yahoo hacmi güvenilmez → halka çizmiyoruz.
        # =F (emtia futures) artık _apply_futures_volume_override ile gerçek CME
        # hacmiyle besleniyor → halka çizmek serbest (gerçek piyasa spike'larını göster).
        _t_sym = st.session_state.get("ticker", "") or ""
        _vol_unreliable = (_t_sym.startswith(("XU", "XB", "XT", "XY", "^"))
                           or "-USD" in _t_sym)
        _layers = [bars, price_line]
        try:
            if (not _vol_unreliable) and 'RVOL' in data.columns and 'Volume' in data.columns:
                _anom = data[data['RVOL'] >= 2.0].copy()
                if not _anom.empty:
                    _anom = _anom.nlargest(5, 'RVOL').sort_values('Date')
                    def _fmt_vol(v):
                        try:
                            v = float(v)
                            if v >= 1e6: return f"{v/1e6:.2f}M"
                            if v >= 1e3: return f"{v/1e3:.0f}K"
                            return f"{v:.0f}"
                        except Exception: return "—"
                    _anom['VolStr']    = _anom['Volume'].apply(_fmt_vol)
                    _anom['VolAvgStr'] = _anom['Vol_Avg20'].apply(_fmt_vol)
                    _anom['RVOLStr']   = _anom['RVOL'].apply(lambda x: f"{x:.2f}x")
                    _anom['LabelStr']  = _anom['RVOL'].apply(lambda x: f"{x:.1f}x")
                    _anom_tooltip = [
                        alt.Tooltip('Date_Str:N',  title='Tarih'),
                        alt.Tooltip('VolStr:N',    title='Hacim'),
                        alt.Tooltip('VolAvgStr:N', title='20g Ort.'),
                        alt.Tooltip('RVOLStr:N',   title='RVOL'),
                        alt.Tooltip('Price:Q',     title='Kapanış', format=_price_fmt),
                    ]
                    _mf_range = float(data['MF_Smooth'].abs().max()) or 1.0
                    _offset   = _mf_range * 0.18
                    _anom['MF_Val'] = _anom.index.map(
                        lambda i: float(data.loc[i, 'MF_Smooth']) if i in data.index else 0.0
                    )
                    _anom['MarkerY'] = _anom.apply(
                        lambda r: r['MF_Val'] + _offset if r['MF_Val'] >= 0 else r['MF_Val'] - _offset,
                        axis=1
                    )
                    # Renk: RVOL < 3 → açık mavi, ≥ 3 → sarı/kırmızı
                    _anom['OuterColor'] = _anom['RVOL'].apply(lambda x: '#38bdf8' if x < 3 else '#fbbf24')
                    _anom['InnerColor'] = _anom['RVOL'].apply(lambda x: '#0369a1' if x < 3 else '#ef4444')
                    _anom['TextColor']  = _anom['RVOL'].apply(lambda x: '#38bdf8' if x < 3 else '#fbbf24')
                    _anom_base  = alt.Chart(_anom).encode(x=x_axis)
                    _anom_y     = alt.Y('MarkerY:Q', axis=None)
                    _ring_outer = _anom_base.mark_point(size=127, filled=True, opacity=0.85).encode(y=_anom_y, color=alt.Color('OuterColor:N', scale=None), tooltip=_anom_tooltip)
                    _ring_inner = _anom_base.mark_point(size=68,  filled=True, opacity=0.95).encode(y=_anom_y, color=alt.Color('InnerColor:N', scale=None), tooltip=_anom_tooltip)
                    _ring_text  = _anom_base.mark_text(dy=-15, fontSize=10, fontWeight='bold', tooltip=None).encode(y=_anom_y, text='LabelStr:N', color=alt.Color('TextColor:N', scale=None))
                    _layers += [_ring_outer, _ring_inner, _ring_text]
        except Exception:
            pass
        st.altair_chart(alt.layer(*_layers).resolve_scale(y='independent').properties(height=280, title=alt.TitleParams(f"🌊 Para Akış İvmesi & Fiyat — {display_ticker}", fontSize=14, color="#38bdf8")), width='stretch')
    with c2:
        _ymin2 = min(data['STP'].min(), data['Price'].min()) * 0.999
        _ymax2 = max(data['STP'].max(), data['Price'].max()) * 1.001
        _ys2   = alt.Scale(zero=False, domain=[_ymin2, _ymax2])
        base2  = alt.Chart(data).encode(x=x_axis)
        _hover2 = alt.selection_point(fields=['Date_Str'], nearest=True, on='mouseover', empty=False)
        _tt2 = [alt.Tooltip('Date_Str:N', title='Tarih'),
                alt.Tooltip('Price:Q',    title='Fiyat', format='.2f'),
                alt.Tooltip('STP:Q',      title='STP',   format='.2f')]
        area       = base2.mark_area(opacity=0.15, color='gray').encode(y=alt.Y('STP:Q', scale=_ys2), y2=alt.Y2('Price:Q'))
        line_stp   = base2.mark_line(color='#fbbf24', strokeWidth=3).encode(y=alt.Y('STP:Q', scale=_ys2, axis=alt.Axis(title='Fiyat', titleColor='#94a3b8')))
        line_price = base2.mark_line(color='#bfdbfe', strokeWidth=2).encode(y=alt.Y('Price:Q', scale=_ys2))
        _vrule2    = base2.mark_rule(color='#94a3b8', strokeWidth=1, strokeDash=[4,3]).encode(
                        opacity=alt.condition(_hover2, alt.value(0.7), alt.value(0)))
        _dot_p2    = base2.mark_point(size=70, color='#bfdbfe', filled=True).encode(
                        y=alt.Y('Price:Q', scale=_ys2), opacity=alt.condition(_hover2, alt.value(1), alt.value(0)))
        _dot_s2    = base2.mark_point(size=70, color='#fbbf24', filled=True).encode(
                        y=alt.Y('STP:Q', scale=_ys2), opacity=alt.condition(_hover2, alt.value(1), alt.value(0)))
        _overlay2  = base2.mark_point(opacity=0, size=200).encode(
                        y=alt.Y('Price:Q', scale=_ys2), tooltip=_tt2).add_params(_hover2)
        st.altair_chart(alt.layer(area, line_stp, line_price, _vrule2, _dot_p2, _dot_s2, _overlay2).properties(
            height=280, title=alt.TitleParams(f"Sentiment — {display_ticker}: Fiyat (mavi) ↔ Eğilim (sarı) — yukarı keserse AL, aşağı keserse SAT", fontSize=14, color="#38bdf8")), width='stretch')


# ── GÖRSEL ANALİZ İNFOGRAFİĞİ (22 Haz 2026) — birebir PNG görünümü, st.html ile ──
# build_widget_html: Plotly temiz grafik + İvme/Denge (SVG) + PARA AKIŞI pusulası +
# Görev 4 kartları, hepsi tek görselde. kaleido ister (chromium/playwright GEREKMEZ).
def _infografik_src_version():
    """İnfografik kaynak dosyalarının son değişiklik zamanı (mtime) → cache-buster.
    Bu dosyalardan biri DÜZENLENİNCE widget önbelleği OTOMATİK yenilenir — artık
    'Clear cache'/restart derdi yok. Prod'da dosya değişmez → önbellek normal çalışır."""
    import os
    _v = 0.0
    _here = os.path.dirname(__file__)
    for _f in ('infografik_build.py', 'clean_chart_plotly.py', 'compass_panel.py', 'infographic.py'):
        try:
            _v = max(_v, os.path.getmtime(os.path.join(_here, _f)))
        except Exception:
            pass
    return round(_v, 1)


@st.cache_data(ttl=1800, show_spinner=False)
def _infografik_widget_html(ticker, datekey, srcver):
    # srcver = kaynak dosyaların mtime'ı; düzenleme olunca değişir → önbellek otomatik tazelenir.
    # 16 Tem 2026: _datekey/_srcver → datekey/srcver. Alt çizgili parametre
    # st.cache_data anahtarına GİRMEZ — tarih/sürüm tazelemesi çalışmıyordu.
    try:
        import infografik_build as _ib
        return _ib.build_widget_html(ticker)
    except Exception as _e:
        return f"__ERR__{_e}"


def _ig_start_bg(ticker):
    """Görsel üretimini ARKA PLANDA başlat (15 Tem 2026 — PARALEL ÜRETİM).
    ÖLÇÜM: build_widget_html ~15.7sn soğuk / ~11.5sn veri sıcakken bile (içinde 3
    ayrı kaleido çizimi var: ana grafik + momentum + ivme). Veri sıcakken de
    düşmemesi maliyetin ÇİZİMDE olduğunu gösterir.
    ÖNCEDEN sıralıydı: sayfa render (~45sn) BİTİP sonra görsel (~15sn) → ~60sn.
    Artık yuva ayrılırken iş burada başlar, sayfanın kalanı çizilirken PARALEL
    koşar; en dipte finalize'a gelindiğinde sonuç çoktan hazırdır → görsel sayfa
    biter bitmez oturur (15sn render'ın içinde saklanır).
    Güvenli: build_widget_html saf hesap (grafik çiz → HTML döndür), st.* çağırmaz.
    add_script_run_ctx → thread içinde st.cache_data normal çalışsın (yoksa cache
    bypass + 'missing ScriptRunContext' uyarısı)."""
    import threading
    _key = (ticker, pd.Timestamp.today().strftime('%Y-%m-%d'), _infografik_src_version())
    # Aynı hedef için koşan iş varsa tekrar başlatma (autorefresh/rerun koruması)
    if (st.session_state.get('_ig_bg_key') == _key
            and st.session_state.get('_ig_bg') is not None):
        return
    _box = {}

    def _work():
        try:
            _box['html'] = _infografik_widget_html(*_key)
        except Exception as _e:
            _box['html'] = f"__ERR__{_e}"

    _th = threading.Thread(target=_work, daemon=True)
    try:
        from streamlit.runtime.scriptrunner import add_script_run_ctx
        add_script_run_ctx(_th)
    except Exception:
        pass
    _th.start()
    st.session_state['_ig_bg']     = (_th, _box)
    st.session_state['_ig_bg_key'] = _key


def _render_infografik_inapp(ticker):
    """Görsel analiz infografiği — 'Para Akış İvmesi' barının yerinde, expander içinde.
    8 Tem 2026 v2: OTOMATİK ama SONA SAKLANMIŞ üretim. Eskiden üretim bu noktada,
    sayfa çizilirken yapılıyordu (~5sn her şeyi bekletir + kaleido/Chrome soğuk
    açılış). Şimdi burada sadece YER AYRILIR; üretim _finalize_infografik_slot ile
    betiğin EN DİBİNDE (sağ kolondan da SONRA) yuvaya konur → sayfanın hiçbir yeri
    beklemez, görsel kendiliğinden yerine gelir.
    15 Tem 2026: üretim ayrıca burada ARKA PLANDA başlatılır (_ig_start_bg) →
    sayfa render'ı ile paralel koşar, en dipte hazır bekler."""
    _disp = get_display_name(ticker)
    with st.expander(f"📊 Görsel Analiz · {_disp} — TIKLA (tüm analiz tek görselde)", expanded=False):
        st.session_state['_ig_slot'] = st.empty()
        st.session_state['_ig_slot_ticker'] = ticker
        with st.session_state['_ig_slot'].container():
            st.caption("📊 Görsel otomatik hazırlanıyor — sayfanın kalanı yüklendikten hemen sonra burada belirir…")
    # Yuva ayrıldı → üretimi ŞİMDİ başlat (sayfanın kalanı çizilirken paralel koşsun)
    _ig_start_bg(ticker)


def _finalize_infografik_slot():
    """Sol kolonun EN SONUNDA çağrılır — ayrılan yuvaya görseli üretip koyar.
    Üretim (kaleido) sayfadaki diğer her şey çizildikten sonra çalıştığı için
    kullanıcı hiçbir paneli beklemez."""
    import streamlit.components.v1 as _comp
    _slot = st.session_state.get('_ig_slot')
    _t = st.session_state.get('_ig_slot_ticker')
    if _slot is None or not _t:
        return
    try:
        # 15 Tem 2026 — arka planda başlayan iş (bkz. _ig_start_bg) burada TOPLANIR.
        # Paralel koştuğu için normalde çoktan bitmiştir → join anında döner.
        _html = None
        _bg = st.session_state.get('_ig_bg')
        if _bg is not None:
            _th, _box = _bg
            _th.join(timeout=120)
            _html = ("__ERR__görsel üretimi 120sn'yi aştı (kaleido takıldı?)"
                     if _th.is_alive() else _box.get('html'))
        if _html is None:   # arka plan iş yok (ilk kurulum/beklenmedik) → eski senkron yol
            _html = _infografik_widget_html(_t, pd.Timestamp.today().strftime('%Y-%m-%d'),
                                            _infografik_src_version())
        # 23 Tem 2026 — ANA KART parçalarını infografiğe ENJEKTE et (ana thread,
        # terazi verisi taze). Grafik önbellekten gelse bile yön/oylar o anki
        # veriden basılır. Paket _render_ekran_v2_deneme'de hazırlandı.
        if _html and not _html.startswith("__ERR__"):
            try:
                _pkt = st.session_state.get('_ekran_v2_paketi') or {}
                if _pkt.get('ticker') == _t and _pkt.get('terazi'):
                    _ter_ig = _pkt['terazi']
                    _yon_ig = _ter_ig.get('yon')
                    _html = _html.replace('<!--EKRANV2_YON-->', ekran_v2.ig_yon(_ter_ig))
                    # 9 Ağu 2026 — infografik üstündeki "İLK EŞİK/İLK DESTEK" kutusu kaldırıldı.
                    _html = _html.replace('<!--EKRANV2_GECERSIZLIK-->', '')
                    _html = _html.replace('<!--EKRANV2_OYLAR-->', '')  # 31 Tem 2026: chip kutusu kaldırıldı (kullanıcı: sadeleşsin)
            except Exception:
                pass  # enjeksiyon başarısızsa infografik yine de basılır (placeholder'lar görünmez yorumdur)

        with _slot.container():
            if _html and not _html.startswith("__ERR__"):
                _comp.html(f"<div style='background:#0a1019;border-radius:12px;'>{_html}</div>",
                           height=1050, scrolling=True)
            else:
                st.caption(f"İnfografik şu an üretilemedi. {(_html or '')[7:][:200]}")
    except Exception as _fe:
        try:
            with _slot.container():
                st.caption(f"İnfografik üretim hatası: {str(_fe)[:150]}")
        except Exception:
            pass
    finally:
        st.session_state['_ig_slot'] = None
        st.session_state['_ig_slot_ticker'] = None
        st.session_state['_ig_bg'] = None
        st.session_state['_ig_bg_key'] = None


def _render_index_participation_panel(ticker):
    """ENDEKS MODU (18 Tem 2026) — endekste 'akıllı para/kurumsal birikim/POC' YASAK
    (100 hissenin toplamı, tek kurum değil). Yerine GENEL PİYASA KATILIMI: bileşen
    kapanış×işlem adedi toplamından yaklaşık katılım (data_layer override). Bot'taki endeks modunun
    ekran karşılığı. Smart Money panelinin yerine geçer (render_smart_volume_panel erken döner)."""
    try:
        df = get_safe_historical_data(ticker, period="3mo")
        if df is None or len(df) < 22:
            return
        v = pd.to_numeric(df['Volume'], errors='coerce')
        v = v[v > 0]
        if len(v) < 22:
            return
        _bugun = float(v.iloc[-1])
        _ort20 = float(v.iloc[-21:-1].mean())
        _pct = (_bugun / _ort20 - 1.0) * 100.0 if _ort20 > 0 else 0.0
        # 5g trend: son 5 ort vs önceki 5 ort
        _son5 = float(v.iloc[-5:].mean()); _onc5 = float(v.iloc[-10:-5].mean())
        _tr_pct = (_son5 / _onc5 - 1.0) * 100.0 if _onc5 > 0 else 0.0
        if _tr_pct > 8:   _tr_txt, _tr_clr = "yükseliyor — katılım artıyor", "#22c55e"
        elif _tr_pct < -8: _tr_txt, _tr_clr = "düşüyor — katılım zayıflıyor", "#f87171"
        else:              _tr_txt, _tr_clr = "yatay — katılım sabit", "#94a3b8"
        def _mlr(x): return f"{x/1e9:.1f} milyar TL" if x >= 1e9 else f"{x/1e6:.0f} milyon TL"
        _pct_clr = "#22c55e" if _pct >= 0 else "#f87171"
        _disp = get_display_name(ticker)
        st.markdown(
            f"<div style='margin:8px 0;border:1px solid #334155;border-radius:10px;overflow:hidden;background:#0b1220;'>"
            f"<div style='background:linear-gradient(90deg,#1e293b,#0f172a);border-bottom:1px solid #334155;"
            f"padding:8px 12px;display:flex;justify-content:space-between;align-items:center;'>"
            f"<span style='font-size:0.9rem;font-weight:800;color:#e2e8f0;'>&#128202; YAKLAŞIK PİYASA KATILIMI</span>"
            f"<span style='font-size:0.75rem;color:#64748b;font-weight:700;'>{_disp}</span></div>"
            f"<div style='padding:12px;'>"
            f"<div style='display:flex;align-items:baseline;gap:10px;margin-bottom:8px;'>"
            f"<span style='font-size:1.7rem;font-weight:900;color:#f1f5f9;'>{_mlr(_bugun)}</span>"
            f"<span style='font-size:0.82rem;font-weight:700;color:{_pct_clr};'>{_pct:+.0f}% (20g ort.)</span></div>"
            f"<div style='font-size:0.78rem;color:#cbd5e1;margin-bottom:5px;'>"
            f"20 günlük yaklaşık katılım ortalaması: <b>{_mlr(_ort20)}</b></div>"
            f"<div style='font-size:0.78rem;color:{_tr_clr};font-weight:600;margin-bottom:9px;'>"
            f"Son 5 gün: {_tr_txt}</div>"
            f"<div style='font-size:0.68rem;color:#64748b;line-height:1.5;border-top:1px solid rgba(100,116,139,0.2);padding-top:7px;'>"
            f"Bu gösterge, eldeki XU100 bileşenlerinin günlük kapanış fiyatı × işlem adedi toplamından "
            f"üretilen yaklaşık piyasa katılımıdır; resmi endeks cirosu değildir. Tek bir kurumun "
            f"alım/satımı DEĞİL — piyasa genelinin yaklaşık katılım ölçüsüdür. Bu yüzden endekste "
            f"'akıllı para / kurumsal birikim / mal toplama' yorumu yapılmaz.</div>"
            f"</div></div>", unsafe_allow_html=True)
    except Exception:
        pass


def _index_has_tl_ciro(ticker):
    """XU100 (ve INDEX_CIRO_TARGETS'taki endeksler) yaklaşık piyasa katılımı göstergesine
    kavuştu (data_layer bileşen-toplamı) → hacim analizinde HİSSE gibi davranır, endeks-susturması
    UYGULANMAZ. Diğer endeks/futures/kripto hâlâ güvenilmez hacim → susturulur."""
    try:
        from data_layer import INDEX_CIRO_TARGETS as _ICT
        return str(ticker).upper().replace(".IS", "") in _ICT
    except Exception:
        return str(ticker).upper().replace(".IS", "") == "XU100"


# 18 Tem 2026 akşam — ENDEKS DİL NORMALLEŞTİRİCİSİ (kullanıcı: "kozmetik değil").
# XU100 zengin hisse panelini kullanıyor ama panel HİSSE diliyle konuşuyor: "akıllı para
# topluyor / kurumların işlem bölgesi / kurumsal birikim" — 100 hissenin TOPLAMINDA tek
# aktör YOK, bunlar YANLIŞ. Panel HTML'ini render'dan önce buradan geçir → tek-aktör dili
# PİYASA GENELİ diline döner. (bot "-meli" kapısının aynı kanıtlanmış deseni; sayılara
# dokunmaz, sadece kelime.) Sıra: çok-kelimeli/özel önce, tek-kelime catch-all sonra.
def _tr_upper(_s):
    """Türkçe'ye saygılı BÜYÜK HARF (14 Ağu 2026).
    Python'un upper()'ı 'i' harfini 'I' yapar → "YENİ" yerine "YENI" çıkıyordu.
    Türkçe'de i→İ, ı→I. Panelde göze görünen etiketlerde bu kullanılır."""
    return str(_s).replace("i", "İ").replace("ı", "I").upper()


