        _frc.close()
        if _fr and _fr[0] is not None:
            _pct = float(_fr[0]); _ust = 100 - _pct
            if _pct >= 70:
                _yorum = f"CMF bakımından tüm BIST'te ÜST %{_ust:.0f} dilimde — alıcı katılımı göreli olarak güçlü"
